import {localTimeToUtc,zonedInput} from './time.js';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="3"/><path d="M7 3v4m10-4v4M3 11h18m-13 5h2m4 0h2"/>',photo:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 6-6 4 4 3-3 5 5"/>',video:'<rect x="3" y="5" width="13" height="14" rx="3"/><path d="m16 10 5-3v10l-5-3z"/>',link:'<path d="m10 13 4-4m-6 6-2 2a4 4 0 0 1-5-5l4-4a4 4 0 0 1 6 0m2 0 2-2a4 4 0 0 1 6 5l-4 4a4 4 0 0 1-6 0" transform="translate(1 1) scale(.9)"/>',settings:'<path d="M12 3v3m0 12v3M3 12h3m12 0h3M5.6 5.6l2.1 2.1m8.6 8.6 2.1 2.1m0-12.8-2.1 2.1m-8.6 8.6-2.1 2.1"/><circle cx="12" cy="12" r="6"/><circle cx="12" cy="12" r="2"/>',plus:'<path d="M12 5v14M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',back:'<path d="M19 12H5m5-5-5 5 5 5"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5"/>',list:'<path d="M8 6h13M8 12h13M8 18h13M3 6h.1M3 12h.1M3 18h.1"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',download:'<path d="M12 3v13m-5-5 5 5 5-5M4 17v4h16v-4"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v2"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="m8 12 3 3 5-6"/>',copy:'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',chevron:'<path d="m9 5 7 7-7 7"/>',crop:'<path d="M6 3v15h15M3 6h15v15"/>',bell:'<path d="M6 8a6 6 0 0 1 12 0c0 8 3 8 3 10H3c0-2 3-2 3-10m4 13h4"/>'})[name]||''}</svg>`;
let state,session,route='planner',draft=null,dirty=false,preview='instagram',listMode='list',statusFilter='all',search='',month=new Date(),mediaFilter='all';
let profiles=[],auditRows=[],users=[],selectedLibrary=new Set(),cropFile=null,cropImage=null;
async function api(path,method='GET',data) {const headers={'x-csrf-token':session?.user?.csrf||''};if(data!==undefined)headers['Content-Type']='application/json';const response=await fetch('/api'+path,{method,headers,body:data===undefined?undefined:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed.');return result;}
function toast(text,error=false){const t=$('#toast');t.textContent=text;t.className=error?'show error':'show';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.className='',6000);}
function size(n){return n>1024*1024?`${(n/1024/1024).toFixed(1)} MB`:`${Math.ceil(n/1024)} KB`;}
function date(iso,full=false){if(!iso)return 'Not scheduled';return new Intl.DateTimeFormat('en-US',{timeZone:state.settings.timezone,month:'short',day:'numeric',...(full?{year:'numeric'}:{}),hour:'numeric',minute:'2-digit'}).format(new Date(iso));}
function badge(status){const labels={draft:'Draft',scheduled:'Scheduled',pending_approval:'Awaiting approval',approved:'Approved',publishing:'Publishing',published:'Published',needs_attention:'Needs attention',partial:'Partially published',archived:'Archived',queued:'Queued',processing:'Processing',manual_action:'Finish in app'};return `<span class="badge ${status}">${esc(labels[status]||status)}</span>`;}
function picon(p){return `<span class="platform-icon ${p.id}">${esc(p.short)}</span>`;}
function thumb(file,cls=''){return file?(file.type.startsWith('video/')?`<video class="${cls}" src="${file.url}" muted preload="metadata" aria-label="${esc(file.name)}"></video>`:`<img class="${cls}" src="${file.url}" alt="${esc(file.alt||file.name)}" loading="lazy">`):`<span class="no-media">${icon('photo')}</span>`;}
function button(text,action,cls='secondary',extra=''){return `<button class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function closeModal(){const modal=$('#modal');modal.close();modal.innerHTML='';if(cropImage){cropImage=null;cropFile=null;}}
function modal(html,wide=false){const el=$('#modal');el.className=wide?'wide':'';el.innerHTML=`<button class="modal-close icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('x')}</button>${html}`;el.showModal();}
async function refresh(){state=await api('/bootstrap');}
function go(to){if(dirty && !confirm('Leave this draft? Changes since your last save will be lost.'))return;dirty=false;location.hash=to;}
function newDraft(kind){draft={title:'',kind,caption:'',product:'',price:'',offer:'',link:'',mediaIds:[],platforms:kind==='photo'?['google_business','facebook','instagram','pinterest']:['facebook','instagram','tiktok','youtube'],variants:{},options:{disable_comment:true,disable_duet:true,disable_stitch:true},locationId:state.settings.locations[0].id,scheduled_at:null};preview=kind==='photo'?'instagram':'youtube';dirty=false;location.hash=`compose-${kind}`;if(route.startsWith('compose'))render();}
function shell(content){const links=[['planner','calendar','Planner'],['library','photo','Media library'],['approvals','shield','Approvals'],['accounts','link','Social accounts'],['settings','settings','Settings']];return `<aside class="sidebar"><a class="brand" href="#planner"><img src="/favicon.svg" alt="" width="38" height="38"><span>storage<span class="brand-light">social</span></span></a><div class="workspace"><span class="avatar">AS</span><div><strong>${esc(state.settings.company)}</strong><small>Company workspace</small></div></div><span class="nav-label">WORKSPACE</span><nav aria-label="Main navigation">${links.map(([r,i,label])=>`<a href="#${r}" class="nav-link ${route===r?'active':''}">${icon(i)}<span>${label}</span>${r==='approvals'&&state.posts.some(p=>p.status==='pending_approval')?`<span class="count">${state.posts.filter(p=>p.status==='pending_approval').length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="storage-note">${icon('shield',18)}<div><strong>Your work, kept together</strong><small>Posts and uploads saved on the server.</small></div></div><div class="profile"><span class="avatar small">${esc((state.user.name||'Owner').slice(0,2).toUpperCase())}</span><div><strong>${esc(state.user.name)}</strong><small>${state.user.localPreview?'Local preview':esc(state.user.role)}</small></div>${!state.user.localPreview?`<button class="icon-btn" data-action="logout" aria-label="Sign out">${icon('arrow',18)}</button>`:''}</div></div></aside><div class="main"><header class="topbar"><span class="breadcrumb">Workspace <span>/</span> <strong>${route.startsWith('compose')?'Create post':({planner:'Planner',library:'Media library',approvals:'Approvals',accounts:'Social accounts',settings:'Settings'})[route]||'Planner'}</strong></span><div class="topbar-right"><span class="muted time-zone">${icon('clock',15)} ${esc(state.settings.timezone)}</span><button class="icon-btn" data-action="attention" aria-label="Posts needing attention">${icon('bell')}</button><span class="avatar small light">AS</span></div></header><main id="content">${content}</main><footer class="app-footer"><span>Storage Social</span><span>AI generation is off · ${state.user.localPreview?'Local workspace':'Private workspace'}</span></footer></div>`;}
function head(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${desc?`<p class="muted">${desc}</p>`:''}</div><div class="head-actions">${actions}</div></div>`;}
function planner(){const active=state.posts.filter(p=>p.status!=='archived');const stats=[['Total posts',active.length,'grid'],['Scheduled',active.filter(p=>p.status==='scheduled').length,'clock'],['Published',active.filter(p=>p.status==='published').length,'check'],['Need attention',active.filter(p=>['needs_attention','partial'].includes(p.status)).length,'bell']];return head('CONTENT WORKSPACE','A little planning. A lot of presence.','Create once, prepare for every channel.',button(`${icon('photo')} Photo post`,'new-photo','primary')+button(`${icon('video')} Video post`,'new-video'))+`<div class="stats">${stats.map(([label,count,i])=>`<div class="stat"><div><span>${label}</span><strong>${count.toString().padStart(2,'0')}</strong></div><span class="stat-icon">${icon(i,22)}</span></div>`).join('')}</div>${!state.providerConfigured?`<div class="notice">${icon('link')}<div><strong>Make yourself at home.</strong> You can upload, draft and plan now. Connect a publishing service when you’re ready to send.</div><a href="#accounts">Set up accounts ${icon('arrow',16)}</a></div>`:''}<section class="panel planner-panel"><div class="panel-toolbar"><div class="view-tabs"><button data-action="list-view" class="${listMode==='list'?'selected':''}">${icon('list',17)} List</button><button data-action="calendar-view" class="${listMode==='calendar'?'selected':''}">${icon('calendar',17)} Calendar</button></div><div class="filters"><label class="search">${icon('search',16)}<input id="search" type="search" placeholder="Search posts…" value="${esc(search)}" aria-label="Search posts"></label><select id="status-filter" aria-label="Filter by status">${['all','draft','scheduled','pending_approval','approved','published','needs_attention','partial','archived'].map(s=>`<option value="${s}" ${statusFilter===s?'selected':''}>${s==='all'?'All statuses':s.replaceAll('_',' ')}</option>`).join('')}</select></div></div><div id="post-results">${postResults()}</div></section><div class="planner-tip">${icon('photo',18)} Photos tell the story. Videos bring it to life. <span>Both belong in the same plan.</span></div>`;}
function filteredPosts(){return state.posts.filter(p=>(statusFilter==='all'?p.status!=='archived':p.status===statusFilter)&&`${p.title} ${p.caption}`.toLowerCase().includes(search.toLowerCase()));}
function postResults(){const posts=filteredPosts();if(listMode==='calendar')return calendar(posts);if(!posts.length)return `<div class="empty"><div class="empty-symbol">${icon('calendar',35)}</div><h2>${state.posts.length?'No matching posts':'Your next post starts here'}</h2><p>${state.posts.length?'Try a different search or status.':'Bring a product into focus with photos, or share the full story with a video.'}</p><div class="empty-actions">${button(`${icon('plus',17)} Create photo post`,'new-photo','primary')}${button('Upload a video','new-video')}</div><div class="empty-channels">${state.platforms.map(p=>picon(p)).join('')}</div></div>`;return `<div class="post-list"><div class="list-heading"><span>POST</span><span>CHANNELS</span><span>STATUS</span><span>PLANNED FOR</span><span></span></div>${posts.map(p=>`<article class="post-row"><button class="post-info" data-action="edit" data-id="${p.id}"><div class="row-thumb">${thumb(state.media.find(m=>m.id===p.mediaIds[0]))}</div><div><strong>${esc(p.title)}</strong><small>${p.kind==='photo'?'Photo post':'Video post'} · ${p.mediaIds.length} file${p.mediaIds.length!==1?'s':''}</small><p>${esc(p.caption||'No caption yet')}</p></div></button><div class="channel-stack">${p.platforms.map(pid=>picon(state.platforms.find(p=>p.id===pid))).join('')}</div><div>${badge(p.status)}</div><div class="post-date">${p.scheduled_at?esc(date(p.scheduled_at)):'<span class="muted">Not scheduled</span>'}</div><button class="icon-btn" data-action="post-menu" data-id="${p.id}" aria-label="Actions for ${esc(p.title)}">${icon('more')}</button></article>`).join('')}</div>`;}
function calendar(posts){const y=month.getFullYear(),m=month.getMonth();const first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),pad=first.getDay();const today=zonedInput(new Date(),state.settings.timezone).slice(0,10);return `<div class="calendar-nav"><h2>${month.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h2><div>${button('←','prev-month')}${button('Today','today')}${button('→','next-month')}</div></div><div class="calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<div class="day-label">${d}</div>`).join('')}${Array.from({length:Math.ceil((pad+days)/7)*7},(_,i)=>{const d=i-pad+1;if(d<1||d>days)return '<div class="day outside"></div>';const key=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;const matches=posts.filter(p=>p.scheduled_at&&zonedInput(p.scheduled_at,state.settings.timezone).startsWith(key));return `<div class="day ${key===today?'today':''}"><span class="day-number">${d}</span>${matches.map(p=>`<button class="calendar-post" data-action="edit" data-id="${p.id}">${icon(p.kind==='photo'?'photo':'video',13)} ${esc(p.title)}<small>${esc(date(p.scheduled_at))}</small></button>`).join('')}</div>`;}).join('')}</div><div class="calendar-caption">Scheduled dates use ${esc(state.settings.timezone)}. Unscheduled drafts appear in List view.</div>`;}
function field(label,id,value='',placeholder='',type='text',extra=''){return `<label class="field">${label}<input id="${id}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${extra}></label>`;}
function composer(){if(!draft)newDraft(route.includes('video')?'video':'photo');const video=draft.kind==='video';return `<div class="composer-heading"><button class="text-btn" data-action="back">${icon('back',17)} Back to planner</button><span id="save-state">${dirty?'Unsaved changes':draft.id?'Saved draft':'New draft'}</span></div>`+head(video?'VIDEO STUDIO':'PHOTO STUDIO',video?'Bring your product to life.':'Put your product in the spotlight.','',button('Save draft','save','secondary')+button(`${icon('calendar',17)} Review & schedule`,'review','primary'))+`<div class="composer-grid"><div class="editor-column"><section class="panel editor-section"><div class="section-label"><span>01</span><h2>${video?'Your video':'Your product photos'}</h2><span class="pill">${video?'VIDEO':'PHOTOS'}</span></div><div class="dropzone" id="dropzone"><div class="upload-symbol">${icon(video?'video':'upload',27)}</div><strong>${video?'Drop your video here':'Drop your product photos here'}</strong><span>${video?'MP4 or MOV · up to 250 MB':'JPG, PNG or WebP · up to 20 MB each'}</span><div>${button('Choose files','upload','secondary')}${button('Browse library','library-picker','text-btn')}</div><input class="visually-hidden" id="file-input" type="file" ${video?'':'multiple'} accept="${video?'video/mp4,video/quicktime':'image/jpeg,image/png,image/webp'}" aria-label="Upload ${video?'video':'photos'}"></div><div class="selected-media" id="selected-media">${selectedMedia()}</div><p class="field-hint">${video?'Videos are submitted separately from photos.':'The first photo is your cover. Use arrows to reorder, or crop a JPEG copy for Instagram.'}</p></section><section class="panel editor-section"><div class="section-label"><span>02</span><h2>The story behind it</h2><span class="ai-off">${icon('spark',14)} AI off</span></div>${field('Post name','post-title',draft.title,'e.g. 20-foot container · September offer')}<details class="product-details" ${draft.product?'open':''}><summary>Product details <span>Optional</span></summary><div class="field-grid">${field('Product name / key features','product',draft.product,'Only confirmed product details')}${field('Price','price',draft.price,'e.g. From $150 / month')}</div>${field('Offer or availability','offer',draft.offer,'e.g. Delivery available in Tucson')}${button('Insert these details into caption','insert-details','text-btn')}<small>Uses your exact details. No AI or invented claims.</small></details><label class="field caption-field">Caption <textarea id="caption" rows="7" placeholder="What would you like your customers to know?">${esc(draft.caption)}</textarea><span class="caption-count" id="caption-count">${draft.caption.length} characters</span></label>${field('Website / product link','post-link',draft.link,'https://storageaz.com','url')}<p class="field-hint">Used for Google’s Learn More button and the Pinterest destination. Include the link in your caption for other channels.</p></section><section class="panel editor-section"><div class="section-label"><span>03</span><h2>Where it goes</h2></div><label class="field">Location<select id="location">${state.settings.locations.map(l=>`<option value="${l.id}" ${draft.locationId===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label><div class="channel-choices">${state.platforms.filter(p=>p.kinds.includes(draft.kind)).map(p=>`<label class="channel-choice ${draft.platforms.includes(p.id)?'checked':''}"><input type="checkbox" data-platform="${p.id}" ${draft.platforms.includes(p.id)?'checked':''}>${picon(p)}<span>${p.name}</span>${icon('check',16)}</label>`).join('')}</div><div id="platform-options">${platformOptions()}</div><details class="variants"><summary>Customize captions by platform</summary>${state.platforms.filter(p=>draft.platforms.includes(p.id)).map(p=>`<label class="field">${p.name}<textarea rows="3" data-variant="${p.id}" placeholder="Use the shared caption">${esc(draft.variants[p.id]||'')}</textarea><small>${p.limit.toLocaleString()} character limit</small></label>`).join('')}</details></section></div><aside class="preview-column"><div class="preview-header"><h2>Post preview</h2><span class="pill">APPROXIMATE</span></div><div class="preview-tabs">${state.platforms.filter(p=>p.kinds.includes(draft.kind)).map(p=>`<button data-action="preview" data-platform-id="${p.id}" class="${preview===p.id?'selected':''}" aria-label="Preview ${p.name}">${picon(p)}</button>`).join('')}</div><div id="preview">${previewCard()}</div><div class="preview-note">${icon('shield',17)} Review the media and wording before publishing. Each platform may display them differently.</div><div class="schedule-card"><h3>${icon('clock',18)} Make room in your calendar</h3><p>Choose when this post should go out.</p><label class="field">Date & time<input id="scheduled-at" type="datetime-local" value="${draft.scheduled_at?zonedInput(draft.scheduled_at,state.settings.timezone):''}"></label><small>${esc(state.settings.timezone)}</small></div></aside></div><div class="composer-bottom"><span>One post. A consistent presence.</span>${button('Save draft','save')}${button('Review & schedule','review','primary')}</div>`;}
function selectedMedia(){return draft.mediaIds.map((mid,i)=>{const m=state.media.find(x=>x.id===mid);return `<div class="media-selected">${thumb(m)}<span class="media-cover">${i===0?'Cover':i+1}</span><div class="media-controls">${i?`<button class="icon-btn" data-action="move-media" data-id="${mid}" aria-label="Move earlier">←</button>`:''}${m?.type.startsWith('image/')?`<button class="icon-btn" data-action="crop" data-id="${mid}" aria-label="Crop ${esc(m.name)}">${icon('crop',15)}</button>`:''}<button class="icon-btn" data-action="remove-media" data-id="${mid}" aria-label="Remove ${esc(m?.name)}">${icon('x',15)}</button></div></div>`;}).join('');}
function platformOptions(){const o=draft.options;return `<div class="options-grid">${draft.platforms.includes('facebook')?field('Facebook Page ID','facebook_page_id',o.facebook_page_id,'Select below or enter your Page ID')+button('Load Facebook Pages','load-options','text-btn','data-platform-id="facebook"'):''}${draft.platforms.includes('pinterest')?field('Pinterest board ID','pinterest_board_id',o.pinterest_board_id,'Required for Pinterest')+button('Load Pinterest boards','load-options','text-btn','data-platform-id="pinterest"'):''}${draft.platforms.includes('google_business')?field('Google location ID','gbp_location_id',o.gbp_location_id,'Optional if only one location is connected')+button('Load Google locations','load-options','text-btn','data-platform-id="google_business"'):''}${draft.platforms.includes('youtube')?`${field('YouTube title','youtube_title',o.youtube_title,'A clear, searchable video title')}<div class="field-grid"><label class="field">YouTube visibility<select id="youtube_privacy"><option value="">Choose visibility</option>${['public','unlisted','private'].map(v=>`<option ${o.youtube_privacy===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Made for kids?<select id="made_for_kids"><option value="">Choose audience</option><option value="false" ${o.made_for_kids===false?'selected':''}>No, not made for kids</option><option value="true" ${o.made_for_kids===true?'selected':''}>Yes, made for kids</option></select></label></div>`:''}${draft.platforms.includes('tiktok')?`<div class="tiktok-settings"><h3>TikTok publishing settings</h3><p class="field-hint">Load the account’s available visibility settings before publishing.</p>${button('Load TikTok settings','load-options','secondary','data-platform-id="tiktok"')}<label class="field">Visibility<select id="privacy_level"><option value="">Choose visibility</option>${(draft.tiktokPrivacyOptions||[o.privacy_level].filter(Boolean)).map(v=>`<option value="${esc(v)}" ${o.privacy_level===v?'selected':''}>${esc(v.replaceAll('_',' ').toLowerCase())}</option>`).join('')}</select></label>${[['disable_comment','Disable comments'],['disable_duet','Disable Duet'],['disable_stitch','Disable Stitch'],['brand_organic_toggle','Promotes our own business'],['brand_content_toggle','Paid partnership with another brand'],['consent','I have reviewed this post and agree to TikTok’s Music Usage Confirmation and, when applicable, Branded Content Policy.']].map(([key,label])=>`<label class="check-label"><input type="checkbox" id="${key}" ${o[key]?'checked':''}>${label}</label>`).join('')}<p class="field-hint"><a href="https://www.tiktok.com/legal/page/global/music-usage-confirmation/en" target="_blank" rel="noopener">Music Usage Confirmation</a> · <a href="https://www.tiktok.com/legal/page/global/bc-policy/en" target="_blank" rel="noopener">Branded Content Policy</a></p></div>`:''}</div>`;}
function previewCard(){const p=state.platforms.find(x=>x.id===preview)||state.platforms[0];const file=state.media.find(m=>m.id===draft.mediaIds[0]);const caption=draft.variants[p.id]||draft.caption;return `<div class="post-preview ${draft.kind}"><div class="preview-account"><span class="avatar light">AS</span><div><strong>${esc(state.settings.company)}</strong><small>${p.name} · Preview</small></div>${icon('more',19)}</div><div class="preview-media">${file?(file.type.startsWith('video/')?`<video controls src="${file.url}" preload="metadata"></video>`:thumb(file)):`<div class="preview-placeholder">${icon(draft.kind==='video'?'video':'photo',46)}<span>${draft.kind==='video'?'Your video will appear here':'Your product, front and center'}</span></div>`}</div><div class="preview-copy">${p.id==='youtube'?`<h3>${esc(draft.options.youtube_title||draft.title||'Your video title')}</h3>`:''}<p>${caption?esc(caption):'<span class="muted">Your caption will appear here as you write.</span>'}</p>${draft.link&&['pinterest','google_business'].includes(p.id)?`<span class="preview-cta">${p.id==='google_business'?'Learn more':'Visit website'} ${icon('arrow',15)}</span>`:''}</div></div><div class="preview-caption-status ${caption.length>p.limit?'over':''}">${caption.length.toLocaleString()} / ${p.limit.toLocaleString()} characters${!draft.platforms.includes(p.id)?' · Not selected for publishing':''}</div>`;}
function library(){const media=state.media.filter(m=>mediaFilter==='all'||m.type.startsWith(mediaFilter+'/'));return head('YOUR ASSETS','A home for your content.','Keep product photos and videos ready for your next post.',button(`${icon('upload')} Upload media`,'library-upload','primary'))+`<section class="panel"><div class="panel-toolbar"><div class="view-tabs">${[['all','All media'],['image','Photos'],['video','Videos']].map(([v,l])=>`<button class="${mediaFilter===v?'selected':''}" data-action="media-filter" data-filter="${v}">${l}</button>`).join('')}</div><span class="muted">${state.media.length} files · ${size(state.media.reduce((n,m)=>n+m.size,0))}</span></div>${media.length?`<div class="media-grid">${media.map(m=>`<article class="asset"><button class="asset-image" data-action="view-media" data-id="${m.id}">${thumb(m)}<span class="asset-type">${icon(m.type.startsWith('video')?'video':'photo',14)}</span></button><div class="asset-info"><strong>${esc(m.name)}</strong><span>${size(m.size)} · ${m.type.split('/')[1].toUpperCase()}</span>${button('Create a post','post-from-media','text-btn',`data-id="${m.id}"`)}</div></article>`).join('')}</div>`:`<div class="empty"><div class="empty-symbol">${icon('photo',35)}</div><h2>Your best content belongs here</h2><p>Upload a product photo or a video to get started.</p>${button('Upload your first file','library-upload','primary')}</div>`}</section><input class="visually-hidden" id="library-file-input" type="file" multiple accept="image/jpeg,image/png,image/webp,video/mp4,video/quicktime" aria-label="Upload media">`;}
function approvals(){const posts=state.posts.filter(p=>p.status==='pending_approval');return head('REVIEW TOGETHER','Ready for a second look.','Review the wording and media before the post is approved.')+`<section class="panel">${posts.length?posts.map(p=>`<article class="approval-row"><div class="row-thumb">${thumb(state.media.find(m=>m.id===p.mediaIds[0]))}</div><div><h3>${esc(p.title)}</h3><p>${esc(p.caption)}</p></div>${button('Review post','edit','secondary',`data-id="${p.id}"`)}</article>`).join(''):`<div class="empty"><div class="empty-symbol">${icon('check',35)}</div><h2>All caught up</h2><p>Posts submitted for approval will appear here.</p></div>`}</section>`;}
function accounts(){return head('CONNECTED CHANNELS','One workspace. Every channel.','Connect your company accounts through the publishing service.',state.providerConfigured?button('Refresh connections','refresh-profiles','secondary'):'')+`${!state.providerConfigured?`<div class="notice setup"><span class="empty-symbol">${icon('link',25)}</span><div><h3>Publishing setup comes next</h3><p>This app includes an Upload-Post integration for account connections and delivery. An owner needs to configure a service account and API key on the server. No subscription has been purchased.</p><p>Your drafts, uploads and calendar work now. Social accounts are not connected yet.</p></div></div>`:''}<div class="accounts-grid">${state.platforms.map(p=>{const connected=profiles.flatMap(profile=>{const a=profile.social_accounts?.[p.id];return a?[{profile:profile.username,account:a}]:[];});return `<section class="panel account-card"><div class="account-heading">${picon(p)}<h2>${p.name}</h2></div><p>${p.kinds.map(k=>k==='photo'?'Photo posts':'Video posts').join(' · ')}</p><span class="connection-status ${connected.length?'connected':''}">${connected.length?'Connection reported by provider':'Not connected'}</span>${connected.map(c=>`<div class="connected-account"><strong>${esc(c.account.display_name||c.account.handle||c.profile)}</strong><small>Profile: ${esc(c.profile)}</small></div>`).join('')}<button class="btn secondary" data-action="connect" ${!state.providerConfigured?'disabled':''}>${icon('plus',16)} ${connected.length?'Manage connection':'Connect account'}</button></section>`;}).join('')}</div><p class="field-hint">Google Business photo posts and a separate TikTok / YouTube video workflow are the launch scope. Live publishing remains subject to account permissions and platform requirements.</p>`;}
function settingsPage(){const s=state.settings;const owner=state.user.role==='owner';return head('WORKSPACE SETTINGS','The details that make it yours.','Company, locations and a safe copy of your work.')+`<div class="settings-grid"><section class="panel editor-section"><h2>Company details</h2>${field('Company name','company',s.company)}${field('Website','website',s.website,'https://storageaz.com','url')}${field('Time zone (IANA)','timezone',s.timezone,'America/Phoenix')}<label class="check-label"><input type="checkbox" id="require-approval" ${s.requireApproval?'checked':''}> Require approval before publishing</label><h3 class="spaced">Locations & publishing profiles</h3><div id="locations">${s.locations.map(l=>`<div class="location-fields" data-location-id="${l.id}">${field('Location name',`loc-name-${l.id}`,l.name)}${field('Upload-Post profile',`loc-profile-${l.id}`,l.profile,'Set after service setup')}</div>`).join('')}</div>${button(`${icon('plus',16)} Add location`,'add-location','text-btn')}${button('Save settings','save-settings','primary',owner?'':'disabled')}<p class="field-hint">Publishing profiles must already exist in Upload-Post. Each location can have its own connected accounts.</p></section><div><section class="panel editor-section backup-card"><span class="backup-icon">${icon('shield',27)}</span><h2>Keep a copy. Keep moving.</h2><p>A full backup includes the database and every uploaded photo and video. Store it somewhere secure.</p><a class="btn primary" href="/api/backup">${icon('download',18)} Download full backup</a><a class="text-btn" href="/api/export">Export post data as JSON</a><p class="field-hint">Backups contain user records and password hashes. Only owners can export full backups. GitHub stores the app code separately.</p></section><section class="panel editor-section"><h2>Simple user guide</h2><p class="muted">Need a quick walkthrough? Open the PDF guide for photo posts, video posts, scheduling, backups, and daily use.</p><a class="btn secondary" href="/storage-social-user-guide.pdf" target="_blank" rel="noopener">${icon('download',17)} Open user guide (PDF)</a></section><section class="panel editor-section"><h2>AI generation</h2><span class="badge draft">Disabled by request</span><p class="muted">Write your own captions and use the product-details helper. This app makes no AI requests.</p></section><section class="panel editor-section"><h2>Team & activity</h2><p class="muted">Owners manage settings; editors prepare posts; approvers review them.</p>${button(`${icon('users',17)} Manage team`,'team','secondary',owner?'':'disabled')}${button('View activity','activity','text-btn')}</section><section class="panel editor-section"><h2>Production address</h2><p class="domain">social.storageaz.com</p><p class="field-hint">This workspace is live and ready for your team.</p></section></div></div>`;}
function render(){if(!state)return;const view=route.startsWith('compose')?composer():({planner,library,approvals,accounts,settings:settingsPage}[route]||planner)();$('#app').innerHTML=shell(view);document.title=`Storage Social · ${route.startsWith('compose')?'Create post':route.charAt(0).toUpperCase()+route.slice(1)}`;}
function updatePreview(){dirty=true;const save=$('#save-state');if(save)save.textContent='Unsaved changes';if($('#preview'))$('#preview').innerHTML=previewCard();if($('#caption-count'))$('#caption-count').textContent=`${draft.caption.length} characters`;}
async function save(){if(!draft.title.trim())throw new Error('Give this post a name before saving.');const result=await api(draft.id?`/posts/${draft.id}`:'/posts',draft.id?'PUT':'POST',draft);draft={...result};dirty=false;await refresh();if($('#save-state'))$('#save-state').textContent='Saved just now';toast('Draft saved.');return result;}
async function upload(files,intoDraft){let uploaded=0;for(const file of files){if(intoDraft&&((draft.kind==='video')!==file.type.startsWith('video/')))throw new Error('Use the separate photo or video workflow for this file.');if(intoDraft&&draft.kind==='video'&&draft.mediaIds.length)throw new Error('Remove the current video before uploading another.');toast(`Uploading ${file.name}…`);const response=await fetch('/api/media',{method:'POST',headers:{'Content-Type':file.type,'X-File-Name':encodeURIComponent(file.name),'X-CSRF-Token':session.user.csrf},body:file});const m=await response.json();if(!response.ok)throw new Error(m.error||'Upload failed.');state.media.unshift(m);if(intoDraft){draft.mediaIds.push(m.id);dirty=true;}uploaded++;}render();toast(`${uploaded} file${uploaded===1?'':'s'} uploaded and saved.`);}
function review(p=draft){const files=p.mediaIds.map(mid=>state.media.find(m=>m.id===mid));const issues=[];if(!p.mediaIds.length)issues.push('Add your photos or video.');if(!p.caption.trim())issues.push('Write a caption.');if(!p.platforms.length)issues.push('Select destinations.');for(const pid of p.platforms){const plat=state.platforms.find(x=>x.id===pid);if((p.variants[pid]||p.caption).length>plat.limit)issues.push(`${plat.name}: caption is too long.`);if(p.kind==='photo'&&p.mediaIds.length>plat.maxPhotos)issues.push(`${plat.name}: choose no more than ${plat.maxPhotos} photo(s) for this release.`);if(pid==='instagram'&&p.kind==='photo'&&files.some(f=>f.type!=='image/jpeg'))issues.push('Instagram: crop/export your photos as JPEG.');}const existing=p.id&&state.posts.find(x=>x.id===p.id);const approved=existing?.status==='approved';const needsApproval=state.settings.requireApproval&&!approved;modal(`<div class="eyebrow">FINAL CHECK</div><h2>Ready to share?</h2><h3>${esc(p.title)}</h3><p class="review-caption">${esc(p.caption)}</p><div class="review-channels">${p.platforms.map(pid=>picon(state.platforms.find(x=>x.id===pid))).join('')}</div>${issues.length?`<div class="validation"><strong>A few details need attention</strong><ul>${issues.map(i=>`<li>${esc(i)}</li>`).join('')}</ul></div>`:''}${!state.providerConfigured?'<div class="notice">Live publishing needs a connected service. You can still save a draft or plan a date; a due post will be marked Needs attention until setup is complete.</div>':''}<p><strong>Planned for:</strong> ${p.scheduled_at?esc(date(p.scheduled_at,true)):'No date selected'}<br><small>${esc(state.settings.timezone)}</small></p><div class="modal-actions">${button('Keep editing','close-modal')}${needsApproval?button('Submit for approval','submit-post','primary',issues.length?'disabled':''):button('Schedule post','schedule-post','primary',(!p.scheduled_at||issues.length)?'disabled':'')}${!needsApproval?button('Publish now','publish-post','secondary',(!state.providerConfigured||issues.length)?'disabled':''):''}</div>`);}
async function showPost(p){if(['draft','approved'].includes(p.status)){draft={...p,options:{...p.options},variants:{...p.variants},mediaIds:[...p.mediaIds]};dirty=false;preview=p.kind==='photo'?'instagram':'youtube';location.hash=`compose-${p.kind}`;render();return;}modal(`<div class="eyebrow">POST DETAILS</div><h2>${esc(p.title)}</h2>${badge(p.status)}<p class="review-caption">${esc(p.caption)}</p><div class="detail-media">${p.mediaIds.map(mid=>thumb(state.media.find(m=>m.id===mid))).join('')}</div><p>${esc(date(p.scheduled_at,true))}</p>${p.deliveries.map(d=>`<div class="delivery-row"><strong>${esc(state.platforms.find(x=>x.id===d.platform)?.name)}</strong>${badge(d.status)}<p>${esc(d.message)}</p>${d.url?`<a href="${esc(d.url)}" target="_blank" rel="noopener">View published post ↗</a>`:''}</div>`).join('')}<div class="modal-actions">${p.status==='pending_approval'&&['owner','approver'].includes(state.user.role)?button('Approve post','approve-post','primary',`data-id="${p.id}"`):''}${!p.deliveries.length&&['scheduled','pending_approval','needs_attention'].includes(p.status)?button('Return to draft','unschedule-post','secondary',`data-id="${p.id}"`):''}${button('Duplicate as draft','duplicate','secondary',`data-id="${p.id}"`)}</div>`,true);}
function cropDraw(){const canvas=$('#crop-canvas');if(!canvas||!cropImage)return;const ctx=canvas.getContext('2d');const ratio=Number($('#crop-ratio').value);const width=1080,height=Math.round(width/ratio);canvas.width=width;canvas.height=height;const sourceRatio=cropImage.naturalWidth/cropImage.naturalHeight;let sw=cropImage.naturalWidth,sh=cropImage.naturalHeight;if(sourceRatio>ratio)sw=sh*ratio;else sh=sw/ratio;const x=(cropImage.naturalWidth-sw)*Number($('#crop-position').value)/100;const y=(cropImage.naturalHeight-sh)*Number($('#crop-position').value)/100;ctx.fillStyle='#ffffff';ctx.fillRect(0,0,width,height);ctx.drawImage(cropImage,x,y,sw,sh,0,0,width,height);}
document.addEventListener('input',e=>{const el=e.target;if(el.id==='search'){search=el.value;$('#post-results').innerHTML=postResults();return;}if(['crop-position','crop-ratio'].includes(el.id)){cropDraw();return;}if(!draft||!route.startsWith('compose'))return;const map={'post-title':'title',caption:'caption',product:'product',price:'price',offer:'offer','post-link':'link',location:'locationId'};if(map[el.id])draft[map[el.id]]=el.value;else if(el.dataset.variant)draft.variants[el.dataset.variant]=el.value;else if(['facebook_page_id','pinterest_board_id','gbp_location_id','youtube_title','youtube_privacy','privacy_level'].includes(el.id))draft.options[el.id]=el.value;else if(el.id==='made_for_kids')draft.options.made_for_kids=el.value===''?undefined:el.value==='true';else if(['disable_comment','disable_duet','disable_stitch','brand_organic_toggle','brand_content_toggle','consent'].includes(el.id))draft.options[el.id]=el.checked;else return;updatePreview();});
document.addEventListener('change',async e=>{try{const el=e.target;if(el.id==='status-filter'){statusFilter=el.value;$('#post-results').innerHTML=postResults();}if(el.id==='scheduled-at'){draft.scheduled_at=null;draft.scheduled_at=localTimeToUtc(el.value,state.settings.timezone);updatePreview();}if(el.dataset.platform){const pid=el.dataset.platform;draft.platforms=el.checked?[...draft.platforms,pid]:draft.platforms.filter(x=>x!==pid);dirty=true;render();}if(el.id==='file-input')await upload(el.files,true);if(el.id==='library-file-input')await upload(el.files,false);if(el.dataset.pickMedia){el.checked?selectedLibrary.add(el.dataset.pickMedia):selectedLibrary.delete(el.dataset.pickMedia);}}catch(err){toast(err.message,true);}});
document.addEventListener('dragover',e=>{if(e.target.closest('#dropzone')){e.preventDefault();$('#dropzone').classList.add('dragging');}});
document.addEventListener('dragleave',e=>{if(e.target.closest('#dropzone'))$('#dropzone')?.classList.remove('dragging');});
document.addEventListener('drop',async e=>{if(e.target.closest('#dropzone')){e.preventDefault();try{await upload(e.dataTransfer.files,true);}catch(err){toast(err.message,true);}}});
document.addEventListener('click',async e=>{
  const link=e.target.closest('a[href^="#"]');if(link&&dirty){e.preventDefault();go(link.getAttribute('href').slice(1));return;}
  const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const action=b.dataset.action,mid=b.dataset.id;const original=b.innerHTML;
  try {
    if(['save','review','schedule-post','publish-post','submit-post','save-settings'].includes(action))b.disabled=true;
    if(action==='new-photo')newDraft('photo');if(action==='new-video')newDraft('video');
    if(action==='back')go('planner');if(action==='close-modal')closeModal();
    if(action==='save')await save();
    if(action==='review'){if(dirty||!draft.id)await save();review();}
    if(['schedule-post','publish-post','submit-post'].includes(action)){const op={'schedule-post':'schedule','publish-post':'publish','submit-post':'submit'}[action];await api(`/posts/${draft.id}/${op}`,'POST',{});closeModal();dirty=false;await refresh();location.hash='planner';render();toast(op==='publish'?'Publishing requested. Track each destination in the planner.':op==='schedule'?'Post scheduled.':'Post submitted for approval.');}
    if(action==='upload')$('#file-input').click();if(action==='library-upload')$('#library-file-input').click();
    if(action==='preview'){preview=b.dataset.platformId;render();}
    if(action==='list-view'){listMode='list';render();}if(action==='calendar-view'){listMode='calendar';render();}
    if(action==='prev-month'||action==='next-month'){month=new Date(month.getFullYear(),month.getMonth()+(action==='prev-month'?-1:1),1);$('#post-results').innerHTML=postResults();}if(action==='today'){month=new Date();$('#post-results').innerHTML=postResults();}
    if(action==='edit')await showPost(state.posts.find(p=>p.id===mid));
    if(action==='remove-media'){draft.mediaIds=draft.mediaIds.filter(x=>x!==mid);dirty=true;render();}
    if(action==='move-media'){const i=draft.mediaIds.indexOf(mid);[draft.mediaIds[i-1],draft.mediaIds[i]]=[draft.mediaIds[i],draft.mediaIds[i-1]];dirty=true;render();}
    if(action==='insert-details'){const bits=[draft.product,draft.price?`Price: ${draft.price}`:'',draft.offer].filter(Boolean);if(!bits.length)throw new Error('Add some product details first.');draft.caption=[draft.caption,...bits].filter(Boolean).join('\n\n');dirty=true;render();}
    if(action==='media-filter'){mediaFilter=b.dataset.filter;render();}
    if(action==='post-from-media'){const file=state.media.find(m=>m.id===mid);newDraft(file.type.startsWith('video/')?'video':'photo');draft.mediaIds=[mid];draft.title=file.name.replace(/\.[^.]+$/,'');dirty=true;render();}
    if(action==='view-media'){const file=state.media.find(m=>m.id===mid);modal(`<h2>${esc(file.name)}</h2>${file.type.startsWith('video/')?`<video class="media-large" controls src="${file.url}"></video>`:`<img class="media-large" src="${file.url}" alt="${esc(file.name)}">`}<p>${size(file.size)}</p><a class="btn secondary" href="${file.url}" download="${esc(file.name)}">Download original</a>`,true);}
    if(action==='library-picker'){selectedLibrary=new Set(draft.mediaIds);modal(`<h2>Choose from your library</h2><div class="picker-grid">${state.media.filter(m=>m.type.startsWith(draft.kind==='video'?'video/':'image/')).map(m=>`<label class="picker-item">${thumb(m)}<span><input type="checkbox" data-pick-media="${m.id}" ${selectedLibrary.has(m.id)?'checked':''}> ${esc(m.name)}</span></label>`).join('')||'<p>No matching files yet. Upload a file to get started.</p>'}</div><div class="modal-actions">${button('Use selected files','use-library','primary')}</div>`,true);}
    if(action==='use-library'){if(draft.kind==='video'&&selectedLibrary.size>1)throw new Error('Choose one video.');if(selectedLibrary.size>10)throw new Error('Choose at most 10 photos.');draft.mediaIds=[...selectedLibrary];dirty=true;closeModal();render();}
    if(action==='crop'){cropFile=state.media.find(m=>m.id===mid);modal(`<h2>Crop a JPEG copy</h2><p>The original stays in your library.</p><label class="field">Aspect ratio<select id="crop-ratio"><option value="1">Square · 1:1</option><option value="0.8">Portrait · 4:5</option><option value="1.7777777778">Landscape · 16:9</option></select></label><canvas id="crop-canvas"></canvas><label class="field">Position<input id="crop-position" type="range" min="0" max="100" value="50"></label>${button('Save cropped copy','save-crop','primary')}`,true);cropImage=new Image();cropImage.onload=cropDraw;cropImage.src=cropFile.url;}
    if(action==='save-crop'){b.disabled=true;const blob=await new Promise(r=>$('#crop-canvas').toBlob(r,'image/jpeg',0.92));if(!blob)throw new Error('Could not create the cropped photo.');const oldId=cropFile.id;const file=new File([blob],cropFile.name.replace(/\.[^.]+$/,'')+'-crop.jpg',{type:'image/jpeg'});const previous=[...draft.mediaIds];await upload([file],true);const newId=draft.mediaIds.at(-1);draft.mediaIds=previous.map(x=>x===oldId?newId:x);closeModal();render();}
    if(action==='post-menu'){const p=state.posts.find(x=>x.id===mid);modal(`<h2>${esc(p.title)}</h2><div class="menu-actions">${button('Open post','open-from-menu','secondary',`data-id="${mid}"`)}${button('Duplicate as draft','duplicate','secondary',`data-id="${mid}"`)}${button('Archive post','archive','secondary',`data-id="${mid}" ${p.status==='publishing'?'disabled':''}`)}</div>`);}
    if(action==='open-from-menu'){closeModal();await showPost(state.posts.find(x=>x.id===mid));}
    if(action==='duplicate'){const p=await api(`/posts/${mid}/duplicate`,'POST',{});closeModal();await refresh();await showPost(p);toast('A new draft copy is ready.');}
    if(action==='archive'){await api(`/posts/${mid}/archive`,'POST',{});closeModal();await refresh();render();toast('Post archived. Find it using the Archived filter.');}
    if(action==='approve-post'||action==='unschedule-post'){await api(`/posts/${mid}/${action==='approve-post'?'approve':'unschedule'}`,'POST',{});closeModal();await refresh();render();toast(action==='approve-post'?'Post approved. Open it to schedule or publish.':'Returned to drafts.');}
    if(action==='attention'){statusFilter='needs_attention';go('planner');render();}
    if(action==='add-location'){const key=crypto.randomUUID();$('#locations').insertAdjacentHTML('beforeend',`<div class="location-fields" data-location-id="${key}">${field('Location name',`loc-name-${key}`,'')}${field('Upload-Post profile',`loc-profile-${key}`,'')}</div>`);}
    if(action==='save-settings'){const locations=[...document.querySelectorAll('[data-location-id]')].map(el=>({id:el.dataset.locationId,name:el.querySelector('input[id^="loc-name-"]').value,profile:el.querySelector('input[id^="loc-profile-"]').value}));await api('/settings','PUT',{company:$('#company').value,website:$('#website').value,timezone:$('#timezone').value,requireApproval:$('#require-approval').checked,locations});await refresh();render();toast('Workspace settings saved.');}
    if(action==='refresh-profiles'){profiles=(await api('/provider/profiles')).profiles;render();toast('Connections refreshed.');}
    if(action==='connect'){modal(`<h2>Connect social accounts</h2><label class="field">Location<select id="connect-location">${state.settings.locations.map(l=>`<option value="${l.id}">${esc(l.name)}</option>`).join('')}</select></label><p>You’ll continue to Upload-Post to securely authorize your accounts.</p>${button('Continue to connection','continue-connect','primary')}`);}
    if(action==='continue-connect'){const result=await api('/provider/connect','POST',{locationId:$('#connect-location').value});location.href=result.url;}
    if(action==='load-options'){const platform=b.dataset.platformId;const data=await api(`/provider/options?location=${encodeURIComponent(draft.locationId)}&platform=${platform}`);if(platform==='tiktok'){const opts=data.privacy_level_options||data.settings?.privacy_level_options||data.data?.privacy_level_options;if(!Array.isArray(opts))throw new Error('The provider did not return TikTok visibility choices. Check the connection.');draft.tiktokPrivacyOptions=opts;$('#platform-options').innerHTML=platformOptions();toast('TikTok visibility options loaded.');}else{const list=data.pages||data.boards||data.locations||data.data?.pages||data.data?.boards||data.data?.locations||[];if(!Array.isArray(list)||!list.length)throw new Error('No destinations returned. Check that the account is connected.');modal(`<h2>Select destination</h2><div class="menu-actions">${list.map(item=>button(esc(item.name||item.title||item.id),'choose-option','secondary',`data-platform-id="${platform}" data-value="${esc(item.id||item.name)}"`)).join('')}</div>`);}}
    if(action==='choose-option'){const key={facebook:'facebook_page_id',pinterest:'pinterest_board_id',google_business:'gbp_location_id'}[b.dataset.platformId];draft.options[key]=b.dataset.value;dirty=true;closeModal();render();}
    if(action==='activity'){auditRows=await api('/audit');modal(`<h2>Workspace activity</h2><div class="activity-list">${auditRows.map(a=>`<div><strong>${esc(a.action.replaceAll('_',' '))}</strong><small>${esc(date(a.created_at,true))}</small></div>`).join('')||'<p>No activity recorded yet.</p>'}</div>`,true);}
    if(action==='team'){users=await api('/users');modal(`<h2>Your team</h2>${users.map(u=>`<p><strong>${esc(u.name)}</strong> · ${esc(u.email)} <span class="pill">${esc(u.role)}</span></p>`).join('')||'<p>No production users yet. Local preview uses a temporary owner identity.</p>'}<details><summary>Add a team member</summary><form id="team-form">${field('Name','team-name')}${field('Email','team-email','','','email')}${field('Initial password (14+ characters)','team-password','','','password','minlength="14" autocomplete="new-password"')}<label class="field">Role<select id="team-role"><option value="editor">Editor</option><option value="approver">Approver</option><option value="owner">Owner</option></select></label><p class="field-hint">Provide this password to your teammate securely. Password reset is an administrator task in this release.</p><button class="btn primary" type="submit">Add team member</button></form></details>`,true);}
    if(action==='logout'){await api('/logout','POST',{});location.reload();}
  }catch(err){toast(err.message,true);}finally{if(b.isConnected){b.disabled=false;b.innerHTML=original;}}
});
document.addEventListener('submit',async e=>{e.preventDefault();try{if(e.target.id==='login-form'){await api('/login','POST',{email:$('#email').value,password:$('#password').value});await init();}if(e.target.id==='team-form'){await api('/users','POST',{email:$('#team-email').value,name:$('#team-name').value,password:$('#team-password').value,role:$('#team-role').value});closeModal();toast('Team member added.');}}catch(err){toast(err.message,true);}});
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'planner';render();window.scrollTo(0,0);});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
async function init(){try{session=await api('/session');if(!session.user){$('#app').innerHTML=`<main class="login-page"><div class="login-card"><img src="/favicon.svg" width="52" height="52" alt="Storage Social"><div class="eyebrow">STORAGE SOCIAL</div><h1>Your content.<br>Your company.</h1><p class="muted">Sign in to your social publishing workspace.</p>${session.setupRequired?'<div class="notice">The owner account needs to be configured on the server before sign-in is available.</div>':''}<form id="login-form">${field('Email','email','','you@company.com','email','required autocomplete="username"')}${field('Password','password','','','password','required autocomplete="current-password"')}<button class="btn primary" type="submit">Sign in ${icon('arrow',17)}</button></form></div></main>`;return;}await refresh();route=location.hash.slice(1)||'planner';render();}catch(err){$('#app').innerHTML=`<div class="loading"><h1>Couldn’t open the workspace</h1><p>${esc(err.message)}</p><a class="btn primary" href="/">Refresh the page</a></div>`;}}
setInterval(async()=>{if(!state||dirty||document.hidden||route.startsWith('compose')||$('#modal').open)return;try{await refresh();if(route==='planner'||route==='approvals')render();}catch{}},30000);
init();
